/**
 * Safe writing of compiled outputs. Decides, per generated file, whether MAP may
 * write it, and performs the writes.
 *
 *   missing    → create
 *   generated  → update when content differs, else unchanged
 *   legacy     → update (older MAP output without a hash)
 *   modified   → conflict: someone edited a generated file
 *   user       → conflict: a hand-written file MAP must not replace
 *   symlink    → conflict: never write through a link
 *
 * With `force`, conflicting files are copied to `<file>.map-backup-<time>` first.
 */

import { basename, dirname, join } from "node:path";
import type { Storage } from "../storage/index.ts";
import type { CompiledOutput, Ownership } from "./compile.ts";
import { ownershipOf } from "./compile.ts";

export type OutputAction = "create" | "update" | "unchanged" | "conflict" | "replace-with-backup";

export interface OutputPlan {
  readonly target: string;
  readonly path: string;
  readonly action: OutputAction;
  readonly ownership?: Ownership | "symlink";
  readonly reason?: string;
  readonly content: string;
}

export async function planOutputs(
  storage: Storage,
  root: string,
  outputs: readonly CompiledOutput[],
  options: { readonly force: boolean },
): Promise<OutputPlan[]> {
  const plans: OutputPlan[] = [];
  for (const output of outputs) {
    const abs = join(root, output.path);
    const base = { target: output.target, path: output.path, content: output.content };
    if (await crossesSymlink(storage, root, output.path)) {
      plans.push({ ...base, action: "conflict", ownership: "symlink", reason: "path is or passes through a symlink; MAP never writes through links" });
      continue;
    }
    if (!(await storage.exists(abs))) {
      plans.push({ ...base, action: "create" });
      continue;
    }
    const existing = await storage.readFile(abs);
    const ownership = ownershipOf(existing);
    if (ownership === "generated" || ownership === "legacy") {
      plans.push({ ...base, ownership, action: existing === output.content ? "unchanged" : "update" });
    } else if (options.force) {
      plans.push({ ...base, ownership, action: "replace-with-backup", reason: "existing file will be backed up first" });
    } else {
      plans.push({
        ...base,
        ownership,
        action: "conflict",
        reason:
          ownership === "user"
            ? "file was not generated by MAP; move its content into .map/ or re-run with --force (a backup is kept)"
            : "generated file was edited by hand; move the edits into .map/ or re-run with --force (a backup is kept)",
      });
    }
  }
  return plans;
}

/** Write the planned files. Returns backups created, as project-relative paths. */
export async function applyOutputs(storage: Storage, root: string, plans: readonly OutputPlan[]): Promise<string[]> {
  const backups: string[] = [];
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  for (const plan of plans) {
    if (plan.action === "unchanged" || plan.action === "conflict") continue;
    const abs = join(root, plan.path);
    await storage.ensureDir(dirname(abs));
    if (plan.action === "replace-with-backup") {
      const backup = join(dirname(plan.path), `${basename(plan.path)}.map-backup-${stamp}`);
      await storage.writeFile(join(root, backup), await storage.readFile(abs), { overwrite: false });
      backups.push(backup);
    }
    await storage.writeFile(abs, plan.content, { overwrite: true });
  }
  return backups;
}

async function crossesSymlink(storage: Storage, root: string, rel: string): Promise<boolean> {
  const segments = rel.split("/");
  let parent = root;
  for (const segment of segments) {
    const entry = (await storage.listEntries(parent)).find((e) => e.name === segment);
    if (entry === undefined) return false;
    if (entry.type === "symlink") return true;
    parent = join(parent, segment);
  }
  return false;
}
